def to_chinese_numeral(n):
    # Mapping of digits to Chinese numerals
    digit_to_chinese = {
        0: '零', 1: '一', 2: '二', 3: '三', 4: '四', 5: '五', 6: '六', 7: '七', 8: '八', 9: '九'
    }

    # Mapping of tens to Chinese numerals
    tens_to_chinese = {
        10: '十', 20: '二十', 30: '三十', 40: '四十', 50: '五十', 60: '六十', 70: '七十', 80: '八十', 90: '九十'
    }

    # Function to convert an integer to Chinese numerals
    def int_to_chinese(num):
        if num == 0:
            return digit_to_chinese[0]
        parts = []
        for i, digit in enumerate(str(num)[::-1]):
            if i == 4:
                parts.append(tens_to_chinese[1000])
            elif i == 8:
                parts.append(tens_to_chinese[10000])
            else:
                if i % 4 == 3 and num % 10 == 0:
                    continue
                parts.append(digit_to_chinese[int(digit)])
                if i % 4 == 2 and int(digit) != 0:
                    parts.append(tens_to_chinese[10 * int(digit)])
        return ''.join(parts[::-1])

    # Convert the integer part
    int_part = int(n)
    chinese_int = int_to_chinese(int_part)

    # Convert the decimal part
    decimal_part = round(n - int_part, 8)
    chinese_dec = ''
    if decimal_part > 0:
        chinese_dec = f'点{int_to_chinese(int(decimal_part * 10 ** 8))}'

    # Combine integer and decimal parts, handling negative numbers
